class Solution:
    def minimumRightShifts(self, nums: List[int]) -> int:
        n = len(nums)
        desc = [i for i in range(n - 1) if nums[i] > nums[i + 1]]
        if not desc:
            return 0
        if len(desc) > 1:
            return -1
        k = desc[0] + 1
        if nums[-1] > nums[0]:
            return -1
        return n - k

c.cpp:
class Solution {
public:
    int minimumRightShifts(vector<int>& nums) {
        int n = nums.size(), k = -1;
        for (int i = 0; i + 1 < n; ++i)
            if (nums[i] > nums[i + 1]) {
                if (k != -1) return -1;
                k = i + 1;
            }
        if (k == -1) return 0;
        if (nums[n - 1] > nums[0]) return -1;
        return n - k;
    }
};

