class Solution {
    public int minimumRightShifts(List<Integer> nums) {
        int n = nums.size(), k = -1;
        for (int i = 0; i + 1 < n; i++)
            if (nums.get(i) > nums.get(i + 1)) {
                if (k != -1) return -1;
                k = i + 1;
            }
        if (k == -1) return 0;
        if (nums.get(n - 1) > nums.get(0)) return -1;
        return n - k;
    }
}

