    let k = -1;
    for (let i = 0; i + 1 < n; i++)
        if (nums[i] > nums[i + 1]) {
            if (k !== -1) return -1;
            k = i + 1;
        }
    if (k === -1) return 0;
    if (nums[n - 1] > nums[0]) return -1;
